    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/change_event_settings',
  headers: {'content-type': 'application/json'},
  body: {
    settings: {
      budget_rom_source_for_in_scope: 'cost',
      budget_rom_source_for_out_of_scope: 'revenue',
      budget_rom_source_for_tbd_scope: 'none',
      celi_prefill_automation: true,
      change_order_value_source: 'latest_cost',
      copy_rfq_attachments_to_commitment_cos: false,
      copy_rfq_attachments_to_prime_cos: true,
      display_revenue_detail_columns: true,
      display_spend_quantity_columns: true,
      prevent_both_prime_cos_and_budget_changes: false,
      sync_wbs_code: true
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/change_event_settings"),
    Content = new StringContent("{\"settings\":{\"budget_rom_source_for_in_scope\":\"cost\",\"budget_rom_source_for_out_of_scope\":\"revenue\",\"budget_rom_source_for_tbd_scope\":\"none\",\"celi_prefill_automation\":true,\"change_order_value_source\":\"latest_cost\",\"copy_rfq_attachments_to_commitment_cos\":false,\"copy_rfq_attachments_to_prime_cos\":true,\"display_revenue_detail_columns\":true,\"display_spend_quantity_columns\":true,\"prevent_both_prime_cos_and_budget_changes\":false,\"sync_wbs_code\":true}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
